/* Фоновая часть плагина «Передача задач».
 *
 * Отвечает за то, что должно работать даже когда панель плагина закрыта:
 *  - регистрация участника в общем файле (чтобы коллеги могли выбрать вас);
 *  - опрос данных плагина и всплывающие уведомления о новых событиях;
 *  - кнопки в шапке и боковой панели.
 *
 * Сама панель живёт в index.html.
 */

const ЯДРО = window.ПередачаЗадач;

const КЛЮЧ_ПРОФИЛЯ = 'передача-задач:профиль';
const КЛЮЧ_ПОКАЗАННЫХ = 'передача-задач:показанные';
const ИНТЕРВАЛ_ОПРОСА_МС = 15000;

// ---------- локальные настройки (не синхронизируются) ----------

function прочитатьПрофиль() {
  try {
    return JSON.parse(localStorage.getItem(КЛЮЧ_ПРОФИЛЯ) || 'null');
  } catch (е) {
    return null;
  }
}

function сохранитьПрофиль(профиль) {
  localStorage.setItem(КЛЮЧ_ПРОФИЛЯ, JSON.stringify(профиль));
}

function прочитатьПоказанные() {
  try {
    return new Set(JSON.parse(localStorage.getItem(КЛЮЧ_ПОКАЗАННЫХ) || '[]'));
  } catch (е) {
    return new Set();
  }
}

function сохранитьПоказанные(множество) {
  localStorage.setItem(КЛЮЧ_ПОКАЗАННЫХ, JSON.stringify(Array.from(множество)));
}

// ---------- участник ----------

/**
 * Заводит профиль при первом запуске и объявляет участника в общем файле.
 * Имя спрашиваем один раз; тег с тем же именем служит отметкой ответственного.
 */
async function обеспечитьПрофиль() {
  let профиль = прочитатьПрофиль();
  if (профиль) return профиль;

  let имя = '';
  try {
    const ответ = await PluginAPI.openDialog({
      title: 'Представьтесь',
      message:
        'Под этим именем вас увидят коллеги, работающие с общим файлом. '
        + 'Задачи, за которые вы отвечаете, будут помечены одноимённым тегом.',
      inputs: [{ id: 'имя', label: 'Ваше имя', type: 'text', required: true }],
      buttons: [{ id: 'ok', label: 'Продолжить', color: 'primary' }],
    });
    имя = ((ответ && (ответ.имя || ответ.values?.имя)) || '').trim();
  } catch (е) {
    console.warn('[Передача задач] диалог знакомства недоступен:', е);
  }

  if (!имя) return null;

  профиль = { id: ЯДРО.новыйId('user'), имя, тег: имя };
  сохранитьПрофиль(профиль);

  await обеспечитьТег(профиль.тег);
  await ЯДРО.дописать(PluginAPI, [
    ЯДРО.создатьОперацию(ЯДРО.ТИПЫ.УЧАСТНИК, профиль.id, {
      userId: профиль.id,
      name: профиль.имя,
      tagTitle: профиль.тег,
    }),
  ]);

  return профиль;
}

/** Создаёт тег участника, если его ещё нет. Возвращает его id. */
async function обеспечитьТег(название) {
  const теги = await PluginAPI.getAllTags();
  const найденный = (теги || []).find((т) => т.title === название);
  if (найденный) return найденный.id;
  return PluginAPI.addTag({ title: название });
}

// ---------- уведомления ----------

/**
 * Показывает всплывающие сообщения о событиях, которых пользователь ещё не
 * видел. Что уже показано — помним локально, чтобы не повторяться на каждом
 * опросе; на других устройствах того же человека уведомление появится снова,
 * и это осознанно: файл не хранит, кто что прочитал.
 */
async function проверитьУведомления(профиль) {
  if (!профиль) return;

  const операции = await ЯДРО.прочитать(PluginAPI);
  const состояние = ЯДРО.собратьСостояние(операции);
  const события = ЯДРО.собратьУведомления(состояние, профиль.id);

  const показанные = прочитатьПоказанные();
  const новые = события.filter((с) => !показанные.has(с.опId));
  if (!новые.length) return;

  // При первом запуске не заваливаем человека историей — показываем свежее.
  const кПоказу = показанные.size === 0 ? новые.slice(0, 1) : новые;

  for (const событие of кПоказу) {
    PluginAPI.showSnack({
      msg: событие.текст,
      type: событие.вид === 'отклонено' ? 'ERROR' : 'SUCCESS',
      ico: событие.вид === 'предложение' ? 'move_to_inbox' : 'sync_alt',
    });
  }

  новые.forEach((с) => показанные.add(с.опId));
  сохранитьПоказанные(показанные);
}

// ---------- запуск ----------

(async function запуск() {
  let профиль = null;
  try {
    профиль = await обеспечитьПрофиль();
  } catch (е) {
    console.error('[Передача задач] не удалось подготовить профиль:', е);
  }

  PluginAPI.registerSidePanelButton({
    label: 'Передача задач',
    icon: 'swap_horiz',
    onClick: () => PluginAPI.showIndexHtmlAsView(),
  });

  PluginAPI.registerHeaderButton({
    label: 'Передача задач',
    icon: 'swap_horiz',
    onClick: () => PluginAPI.showIndexHtmlAsView(),
  });

  PluginAPI.registerMenuEntry({
    label: 'Передача задач',
    icon: 'swap_horiz',
    onClick: () => PluginAPI.showIndexHtmlAsView(),
  });

  if (!профиль) return;

  await проверитьУведомления(профиль).catch((е) =>
    console.warn('[Передача задач] проверка уведомлений не удалась:', е));

  setInterval(() => {
    проверитьУведомления(профиль).catch((е) =>
      console.warn('[Передача задач] проверка уведомлений не удалась:', е));
  }, ИНТЕРВАЛ_ОПРОСА_МС);
})();
